-- ---- SLA definitions (P0-P3) -----------------------------------------------
insert into iris.sla_definitions (priority, name, description, response_target_mins, resolution_target_mins,
  escalation_threshold_mins, business_hours_only, auto_actions, escalation_rules, resolution_rules, triggers) values
  ('P0', 'Critical', 'Safety incidents, major studio operational disruptions, critical system failures affecting multiple operations. Immediate intervention required.', 15, 240, 30, false, '[{"id":"P0-A1","trigger":"On ticket creation","action":"Notify assignee + department head + studio director immediately via in-app, email, and WhatsApp","type":"notify","target":"Assignee + Department Head + Studio Director","timing":"0 min","automatic":true},{"id":"P0-A2","trigger":"No acknowledgment in 5 minutes","action":"Auto-escalate to next-level contact and notify director","type":"escalate","target":"Escalation Chain L2","timing":"5 min","automatic":true},{"id":"P0-A3","trigger":"No response in 15 minutes","action":"Escalate to all stakeholders, trigger emergency protocol","type":"escalate","target":"All stakeholders + Director","timing":"15 min","automatic":true},{"id":"P0-A4","trigger":"30 minutes without resolution progress","action":"Auto-create escalation ticket and notify management","type":"escalate","target":"Management","timing":"30 min","automatic":true},{"id":"P0-A5","trigger":"4 hours without resolution","action":"Critical breach — notify board, activate incident response","type":"escalate","target":"Board + All Directors","timing":"4 hours","automatic":true}]'::jsonb, '[{"id":"P0-E1","trigger":"5 min no response","condition":"firstResponseAt is null AND now > created + 5min","escalateTo":"L2 — Department Manager","timeframe":"5 min","automatic":true},{"id":"P0-E2","trigger":"15 min no response","condition":"firstResponseAt is null AND now > created + 15min","escalateTo":"L3 — Studio Director","timeframe":"15 min","automatic":true},{"id":"P0-E3","trigger":"30 min unresolved","condition":"status != resolved AND now > created + 30min","escalateTo":"L4 — India Director","timeframe":"30 min","automatic":true},{"id":"P0-E4","trigger":"2 hours unresolved","condition":"status != resolved AND now > created + 2h","escalateTo":"L5 — Emergency Response Team","timeframe":"2 hours","automatic":true},{"id":"P0-E5","trigger":"4 hours (SLA breach)","condition":"status != resolved AND now > created + 4h","escalateTo":"Board Notification","timeframe":"4 hours","automatic":true}]'::jsonb, '[{"id":"P0-R1","trigger":"Status changed to resolved","condition":"assignee confirms resolution with verified action","action":"Require Quality Agent verification before closure","automatic":true},{"id":"P0-R2","trigger":"Auto-resolve attempt","condition":"system action succeeded (API response verified)","action":"Mark as auto-resolved with audit entry, notify reporter for confirmation","automatic":true},{"id":"P0-R3","trigger":"Reopen within 24h","condition":"reporter reopens ticket","action":"Auto-escalate to P0+ priority, notify director immediately","automatic":true}]'::jsonb, '[{"id":"P0-T1","event":"ticket_created","condition":"priority = P0","action":"Immediate notification blast (in-app + email + WhatsApp) to assignee, dept head, director","timing":"0 min"},{"id":"P0-T2","event":"sla_50%","condition":"elapsed > 50% of resolution target","action":"Notify assignee of approaching deadline","timing":"2 hours"},{"id":"P0-T3","event":"sla_75%","condition":"elapsed > 75% of resolution target","action":"Warn assignee + notify department head","timing":"3 hours"},{"id":"P0-T4","event":"sla_breached","condition":"now > resolutionTarget","action":"Critical breach alert to all stakeholders","timing":"4 hours"},{"id":"P0-T5","event":"no_acknowledgment","condition":"firstResponseAt is null AND elapsed > 5min","action":"Auto-escalate to L2","timing":"5 min"}]'::jsonb),
  ('P1', 'High', 'Significant client-facing disruptions, payment or membership issues with substantial impact, essential equipment failures, issues affecting scheduled classes or service delivery.', 60, 720, 90, false, '[{"id":"P1-A1","trigger":"On ticket creation","action":"Notify assignee via in-app + email immediately","type":"notify","target":"Assignee","timing":"0 min","automatic":true},{"id":"P1-A2","trigger":"No acknowledgment in 30 minutes","action":"Notify department head","type":"notify","target":"Department Head","timing":"30 min","automatic":true},{"id":"P1-A3","trigger":"No response in 60 minutes","action":"Escalate to department manager, flag SLA risk","type":"escalate","target":"Department Manager","timing":"60 min","automatic":true},{"id":"P1-A4","trigger":"6 hours without resolution","action":"Escalate to operations manager","type":"escalate","target":"Operations Manager","timing":"6 hours","automatic":true},{"id":"P1-A5","trigger":"12 hours (SLA breach)","action":"Notify studio director, mark as breached","type":"escalate","target":"Studio Director","timing":"12 hours","automatic":true}]'::jsonb, '[{"id":"P1-E1","trigger":"30 min no response","condition":"firstResponseAt is null AND now > created + 30min","escalateTo":"L2 — Department Manager","timeframe":"30 min","automatic":true},{"id":"P1-E2","trigger":"60 min no response","condition":"firstResponseAt is null AND now > created + 60min","escalateTo":"L3 — Operations Manager","timeframe":"60 min","automatic":true},{"id":"P1-E3","trigger":"6 hours unresolved","condition":"status != resolved AND now > created + 6h","escalateTo":"L4 — Studio Director","timeframe":"6 hours","automatic":true},{"id":"P1-E4","trigger":"12 hours (SLA breach)","condition":"status != resolved AND now > created + 12h","escalateTo":"L5 — Director + Board notification","timeframe":"12 hours","automatic":true}]'::jsonb, '[{"id":"P1-R1","trigger":"Status changed to resolved","condition":"assignee confirms resolution","action":"Notify reporter, start 48h reopen window","automatic":true},{"id":"P1-R2","trigger":"Auto-resolve attempt","condition":"system action succeeded and verified","action":"Mark as auto-resolved, require reporter confirmation within 48h","automatic":true},{"id":"P1-R3","trigger":"48h reopen window expired","condition":"reporter did not reopen","action":"Auto-close ticket, log resolution metrics","automatic":true}]'::jsonb, '[{"id":"P1-T1","event":"ticket_created","condition":"priority = P1","action":"Notify assignee + email","timing":"0 min"},{"id":"P1-T2","event":"sla_50%","condition":"elapsed > 50%","action":"Notify assignee — halfway reminder","timing":"6 hours"},{"id":"P1-T3","event":"sla_75%","condition":"elapsed > 75%","action":"Warn assignee + dept head","timing":"9 hours"},{"id":"P1-T4","event":"3h_before_due","condition":"remaining = 3h","action":"Send ''due in 3 hours'' email to assignee","timing":"9 hours"},{"id":"P1-T5","event":"due_today","condition":"resolution target is today","action":"Send ''due today'' email","timing":"Today"},{"id":"P1-T6","event":"sla_breached","condition":"now > resolutionTarget","action":"Breach alert to director","timing":"12 hours"},{"id":"P1-T7","event":"3h_past_due","condition":"now > resolutionTarget + 3h","action":"Send ''3 hours past due'' alert","timing":"15 hours"}]'::jsonb),
  ('P2', 'Medium', 'Individual client requests, non-critical technical issues, maintenance requirements that do not immediately disrupt operations.', 240, 2880, 360, true, '[{"id":"P2-A1","trigger":"On ticket creation","action":"Notify assignee via in-app notification","type":"notify","target":"Assignee","timing":"0 min","automatic":true},{"id":"P2-A2","trigger":"No acknowledgment in 4 hours","action":"Send reminder to assignee","type":"notify","target":"Assignee","timing":"4 hours","automatic":true},{"id":"P2-A3","trigger":"No response in 8 hours","action":"Notify department manager","type":"notify","target":"Department Manager","timing":"8 hours","automatic":true},{"id":"P2-A4","trigger":"24 hours without resolution","action":"Escalate to department manager","type":"escalate","target":"Department Manager","timing":"24 hours","automatic":true},{"id":"P2-A5","trigger":"48 hours (SLA breach)","action":"Escalate to operations manager, mark as breached","type":"escalate","target":"Operations Manager","timing":"48 hours","automatic":true}]'::jsonb, '[{"id":"P2-E1","trigger":"8 hours no response","condition":"firstResponseAt is null AND now > created + 8h","escalateTo":"L2 — Department Manager","timeframe":"8 hours","automatic":true},{"id":"P2-E2","trigger":"24 hours unresolved","condition":"status != resolved AND now > created + 24h","escalateTo":"L3 — Operations Manager","timeframe":"24 hours","automatic":true},{"id":"P2-E3","trigger":"48 hours (SLA breach)","condition":"status != resolved AND now > created + 48h","escalateTo":"L4 — Studio Director","timeframe":"48 hours","automatic":true}]'::jsonb, '[{"id":"P2-R1","trigger":"Status changed to resolved","condition":"assignee confirms resolution","action":"Notify reporter, start 72h reopen window","automatic":true},{"id":"P2-R2","trigger":"Auto-resolve (low-risk)","condition":"reversible action verified (e.g., credit adjustment)","action":"Auto-resolve with audit entry","automatic":true},{"id":"P2-R3","trigger":"72h reopen window expired","condition":"reporter did not reopen","action":"Auto-close ticket","automatic":true}]'::jsonb, '[{"id":"P2-T1","event":"ticket_created","condition":"priority = P2","action":"In-app notify assignee","timing":"0 min"},{"id":"P2-T2","event":"4h_no_ack","condition":"firstResponseAt is null AND elapsed > 4h","action":"Reminder to assignee","timing":"4 hours"},{"id":"P2-T3","event":"sla_50%","condition":"elapsed > 50%","action":"Notify assignee — halfway reminder","timing":"24 hours"},{"id":"P2-T4","event":"sla_75%","condition":"elapsed > 75%","action":"Warn assignee + dept head","timing":"36 hours"},{"id":"P2-T5","event":"sla_breached","condition":"now > resolutionTarget","action":"Breach alert to ops manager","timing":"48 hours"}]'::jsonb),
  ('P3', 'Low', 'General enquiries, minor improvements, non-urgent administrative requests.', 720, 10080, 1440, true, '[{"id":"P3-A1","trigger":"On ticket creation","action":"Add to department queue, notify assignee","type":"notify","target":"Assignee","timing":"0 min","automatic":true},{"id":"P3-A2","trigger":"No acknowledgment in 12 hours","action":"Send reminder","type":"notify","target":"Assignee","timing":"12 hours","automatic":true},{"id":"P3-A3","trigger":"3 days without resolution","action":"Notify department manager","type":"notify","target":"Department Manager","timing":"3 days","automatic":true},{"id":"P3-A4","trigger":"7 days (SLA breach)","action":"Escalate to operations manager","type":"escalate","target":"Operations Manager","timing":"7 days","automatic":true}]'::jsonb, '[{"id":"P3-E1","trigger":"12 hours no response","condition":"firstResponseAt is null AND now > created + 12h","escalateTo":"L2 — Department Manager","timeframe":"12 hours","automatic":true},{"id":"P3-E2","trigger":"3 days unresolved","condition":"status != resolved AND now > created + 3d","escalateTo":"L3 — Operations Manager","timeframe":"3 days","automatic":true},{"id":"P3-E3","trigger":"7 days (SLA breach)","condition":"status != resolved AND now > created + 7d","escalateTo":"L4 — Studio Director","timeframe":"7 days","automatic":true}]'::jsonb, '[{"id":"P3-R1","trigger":"Status changed to resolved","condition":"assignee confirms","action":"Notify reporter, start 7-day reopen window","automatic":true},{"id":"P3-R2","trigger":"7 days reopen window expired","condition":"reporter did not reopen","action":"Auto-close ticket","automatic":true}]'::jsonb, '[{"id":"P3-T1","event":"ticket_created","condition":"priority = P3","action":"Add to queue, notify assignee","timing":"0 min"},{"id":"P3-T2","event":"12h_no_ack","condition":"firstResponseAt is null AND elapsed > 12h","action":"Reminder","timing":"12 hours"},{"id":"P3-T3","event":"sla_50%","condition":"elapsed > 50%","action":"Notify — halfway","timing":"3.5 days"},{"id":"P3-T4","event":"sla_breached","condition":"now > resolutionTarget","action":"Breach alert","timing":"7 days"}]'::jsonb)
on conflict (priority) do update set name = excluded.name, description = excluded.description,
  response_target_mins = excluded.response_target_mins, resolution_target_mins = excluded.resolution_target_mins,
  escalation_threshold_mins = excluded.escalation_threshold_mins, business_hours_only = excluded.business_hours_only,
  auto_actions = excluded.auto_actions, escalation_rules = excluded.escalation_rules,
  resolution_rules = excluded.resolution_rules, triggers = excluded.triggers;

-- ---- Ticket templates (111) ------------------------------------------------
insert into iris.templates (code, title, description, category, subcategory, department_code, default_priority,
  default_severity, suggested_assignee_role, required_fields, conditional_fields, custom_fields, prefilled_options,
  recommended_actions, estimated_resolution_hours) values
  ('TPL-001', 'Membership Incorrectly Frozen', 'Client reports that their membership has been frozen without request or remains frozen past scheduled unfreeze date.', 'Membership', 'Freeze Issue', 'MEM', 'P2', 'Medium', 'Memberships Manager', array['clientName', 'studio', 'membershipType']::text[], '[{"field":"freezeType","condition":"Was freeze scheduled?","options":["Scheduled freeze","Unexpected freeze","Failed to unfreeze"]},{"field":"duration","condition":"How long has it been frozen?","options":["< 24 hours","1-3 days","> 3 days"]}]'::jsonb, '[{"name":"membershipId","type":"text"},{"name":"momenceMemberId","type":"text"}]'::jsonb, '[{"field":"studio","options":["Kwality House","Supreme HQ","Kenkere House","Pop Up"]}]'::jsonb, '1. Verify freeze status in Momence.
2. Check if freeze was scheduled or system-triggered.
3. If incorrect, unfreeze and apply credit if applicable.
4. Notify client and confirm resolution.', 4),
  ('TPL-002', 'Class Credits Not Reflecting', 'Member reports purchased class credits are not showing correctly in Momence.', 'Membership', 'Credit Discrepancy', 'MEM', 'P2', null, 'Memberships Manager', array['clientName', 'studio', 'packageType']::text[], '[{"field":"discrepancyType","condition":"What is the discrepancy?","options":["Fewer credits than purchased","Credits not appearing at all","Credits expired early","Wrong package credited"]}]'::jsonb, '[{"name":"purchasedCredits","type":"number"},{"name":"showingCredits","type":"number"},{"name":"purchaseDate","type":"date"}]'::jsonb, '[]'::jsonb, 'Investigate purchase transaction in Momence, compare with displayed credits, apply credit adjustment if verified.', 6),
  ('TPL-003', 'Membership Change Request', 'Client wants to change membership type (upgrade, downgrade, switch).', 'Membership', 'Change Request', 'MEM', 'P3', null, 'Memberships Associate', array['clientName', 'currentMembership', 'desiredMembership']::text[], '[{"field":"changeType","condition":"Type of change?","options":["Upgrade","Downgrade","Switch plan","Add-on package"]},{"field":"effectiveDate","condition":"When should it take effect?","options":["Immediately","Next billing cycle","Specific date"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Confirm new membership terms, calculate proration, process change in Momence with client confirmation.', 24),
  ('TPL-004', 'Membership Cancellation Request', 'Client requests cancellation of their membership.', 'Membership', 'Cancellation', 'MEM', 'P2', null, 'Memberships Manager', array['clientName', 'membershipType', 'reason']::text[], '[{"field":"cancellationReason","condition":"Reason for cancellation?","options":["Relocation","Financial","Dissatisfaction","Medical","Other"]},{"field":"effectiveDate","condition":"When to cancel?","options":["Immediate","End of billing cycle","Specific date"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review cancellation policy, process cancellation in Momence, confirm final billing and access end date.', 48),
  ('TPL-005', 'Refund Request — Membership', 'Client requests refund for membership purchase.', 'Membership', 'Refund', 'PAY', 'P2', null, 'Finance Manager', array['clientName', 'amount', 'purchaseReference']::text[], '[{"field":"refundReason","condition":"Reason for refund?","options":["Duplicate charge","Service not delivered","Cancellation within window","Billing error","Client request"]},{"field":"refundType","condition":"Refund type?","options":["Full","Partial","Credit to account"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify original payment in Momence, check refund policy, process refund through payment gateway, log audit entry.', 72),
  ('TPL-006', 'Membership Payment Failed', 'Automatic membership renewal payment has failed.', 'Membership', 'Payment Issue', 'PAY', 'P1', null, 'Finance Manager', array['clientName', 'membershipType', 'paymentMethod']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Check payment gateway for failure reason, contact client to update payment method, retry payment.', 24),
  ('TPL-007', 'Duplicate Membership Charge', 'Client has been charged twice for the same membership.', 'Membership', 'Billing Error', 'PAY', 'P1', null, 'Finance Manager', array['clientName', 'amount', 'transactionIds']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify duplicate transactions, process refund for duplicate, notify client.', 24),
  ('TPL-008', 'Membership Renewal Issue', 'Membership did not renew automatically as expected.', 'Membership', 'Renewal', 'MEM', 'P2', null, 'Memberships Manager', array['clientName', 'membershipType']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Check auto-renewal status, verify payment method, process manual renewal if needed.', 24),
  ('TPL-009', 'Membership Transfer Between Studios', 'Client requests to transfer membership between Mumbai and Bengaluru studios.', 'Membership', 'Transfer', 'MEM', 'P3', null, 'Memberships Manager', array['clientName', 'fromStudio', 'toStudio']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify membership terms allow transfer, update studio assignment in Momence, notify both studios.', 48),
  ('TPL-010', 'Promotional Code Not Applying', 'Client reports that a promotional code is not being applied at checkout.', 'Membership', 'Promo Code', 'MEM', 'P3', null, 'Memberships Associate', array['clientName', 'promoCode', 'intendedPurchase']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify promo code validity and terms, check expiration, apply manually if valid.', 4),
