  ('TPL-078', 'Client Feedback — Positive', 'Client has provided positive feedback about their experience.', 'Client Experience', 'Feedback', 'MGT', 'P3', null, 'Operations Manager', array['clientName', 'feedbackDescription', 'staffMentioned']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Acknowledge feedback, share with mentioned staff, consider for recognition program.', 24),
  ('TPL-079', 'Client Feedback — Improvement Suggestion', 'Client has suggested an improvement to services or facilities.', 'Client Experience', 'Suggestion', 'MGT', 'P3', null, 'Operations Manager', array['clientName', 'suggestionDescription']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review suggestion, evaluate feasibility, respond to client with appreciation, implement if appropriate.', 168),
  ('TPL-080', 'Client Request — Special Accommodation', 'Client requests special accommodation (medical, accessibility, etc.).', 'Client Experience', 'Accommodation', 'MEM', 'P2', null, 'Memberships Manager', array['clientName', 'accommodationType', 'details']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review request, coordinate with instructor and front desk, document accommodation, ensure implementation.', 48),
  ('TPL-081', 'Lost Item Report', 'Client reports lost item at studio.', 'Client Experience', 'Lost & Found', 'FRT', 'P3', null, 'Front Desk Associate', array['clientName', 'studio', 'itemDescription', 'lastSeenLocation']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Check lost and found, notify all studios, follow up with client, log found items.', 48),
  ('TPL-082', 'Client Behavior Issue', 'Issue with client behavior affecting other clients or staff.', 'Client Experience', 'Conduct', 'MGT', 'P2', null, 'Operations Manager', array['clientName', 'studio', 'behaviorDescription', 'witnessDetails']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Investigate incident, speak with client if appropriate, document, escalate if pattern emerges.', 48),
  ('TPL-083', 'Client Cancellation Policy Dispute', 'Client disputes cancellation charges based on policy.', 'Client Experience', 'Policy Dispute', 'MEM', 'P2', null, 'Memberships Manager', array['clientName', 'disputeDetails', 'amount']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review cancellation policy, verify client circumstances, resolve per policy or escalate exception.', 48),
  ('TPL-084', 'Birthday/Special Occasion Acknowledgment', 'Client has birthday or special occasion — needs acknowledgment.', 'Client Experience', 'Engagement', 'MKT', 'P3', null, 'Marketing Manager', array['clientName', 'occasion', 'date']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Send personalized message, consider small gesture (free class credit, etc.), document in member notes.', 4),
  ('TPL-085', 'VIP Client Request', 'VIP or high-value client has special request.', 'Client Experience', 'VIP', 'MGT', 'P2', null, 'Studio Director', array['clientName', 'requestDescription']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Prioritize request, coordinate with relevant departments, ensure VIP treatment, follow up personally.', 24),
  ('TPL-086', 'Staff Leave Request', 'Employee requesting leave.', 'HR', 'Leave', 'HRV', 'P3', null, 'HR Manager', array['employeeName', 'leaveType', 'startDate', 'endDate']::text[], '[{"field":"leaveType","condition":"Type of leave?","options":["Annual","Sick","Personal","Maternity/Paternity","Unpaid"]}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify leave balance, check coverage, approve/deny with reason, update schedule.', 24),
  ('TPL-087', 'Staff Schedule Conflict', 'Employee reports scheduling conflict.', 'HR', 'Scheduling', 'SCH', 'P2', null, 'Scheduling Manager', array['employeeName', 'conflictDescription', 'affectedShifts']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review schedule, arrange coverage if possible, update schedule, notify affected parties.', 8),
  ('TPL-088', 'Payroll Discrepancy', 'Employee reports payroll discrepancy.', 'HR', 'Payroll', 'HRV', 'P2', null, 'HR Manager', array['employeeName', 'discrepancyType', 'amount', 'payPeriod']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify timesheet, check payroll records, identify discrepancy, process correction if needed.', 72),
  ('TPL-089', 'New Employee Onboarding', 'New employee joining — needs onboarding setup.', 'HR', 'Onboarding', 'HRV', 'P2', null, 'HR Manager', array['employeeName', 'role', 'startDate', 'assignedStudio']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Create employee record, set up accounts (email, Momence access), prepare onboarding materials, schedule orientation.', 48),
  ('TPL-090', 'Employee Offboarding', 'Employee leaving — needs offboarding process.', 'HR', 'Offboarding', 'HRV', 'P2', null, 'HR Manager', array['employeeName', 'lastWorkingDay', 'reason']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Recover equipment, revoke system access, complete exit formalities, conduct exit interview.', 72),
  ('TPL-091', 'Performance Issue', 'Performance issue with employee reported.', 'HR', 'Performance', 'HRV', 'P2', null, 'HR Manager', array['employeeName', 'issueDescription', 'reportedBy']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Investigate issue, schedule meeting with employee, document discussion, create improvement plan if needed.', 168),
  ('TPL-092', 'Training Request', 'Employee requests training or professional development.', 'HR', 'Training', 'HRV', 'P3', null, 'HR Manager', array['employeeName', 'trainingType', 'justification', 'estimatedCost']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review request, verify budget, approve/deny, schedule training if approved.', 168),
  ('TPL-093', 'Employee Grievance', 'Employee has raised a grievance.', 'HR', 'Grievance', 'HRV', 'P2', null, 'HR Manager', array['employeeName', 'grievanceDescription', 'againstParty']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Acknowledge grievance, investigate confidentially, schedule mediation if needed, document resolution.', 168),
  ('TPL-094', 'Uniform/Dress Code Issue', 'Employee needs uniform replacement or has dress code concern.', 'HR', 'Uniform', 'HRV', 'P3', null, 'HR Manager', array['employeeName', 'issueDescription']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Order replacement if needed, communicate dress code if concern, follow up.', 168),
  ('TPL-095', 'Employee Recognition Nomination', 'Employee nominated for recognition.', 'HR', 'Recognition', 'HRV', 'P3', null, 'HR Manager', array['employeeName', 'nominatedBy', 'reason']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review nomination, process recognition, notify employee, document in file.', 72),
  ('TPL-096', 'Campaign Setup Request', 'Marketing campaign needs to be set up.', 'Marketing', 'Campaign', 'MKT', 'P3', null, 'Marketing Manager', array['campaignName', 'type', 'startDate', 'endDate', 'budget']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Plan campaign, set up in marketing platform, coordinate with studios, execute, track results.', 168),
  ('TPL-097', 'Social Media Content Request', 'Studio requests social media content creation.', 'Marketing', 'Content', 'MKT', 'P3', null, 'Marketing Manager', array['studio', 'contentType', 'purpose', 'deadline']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Plan content, schedule shoot if needed, create and review, publish, track engagement.', 96),
  ('TPL-098', 'Email Campaign Request', 'Request to send email campaign to members.', 'Marketing', 'Email', 'MKT', 'P3', null, 'Marketing Manager', array['campaignName', 'audience', 'content', 'schedule']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Draft email, review content, set up in email platform, test, schedule, track results.', 72),
  ('TPL-099', 'Promotional Offer Setup', 'Set up promotional offer in Momence.', 'Marketing', 'Promotion', 'MKT', 'P3', null, 'Marketing Manager', array['offerName', 'details', 'duration', 'targetAudience']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Configure in Momence, set up landing page, coordinate with front desk, track redemptions.', 48),
  ('TPL-100', 'Member Communication Request', 'Need to communicate specific information to members.', 'Marketing', 'Communication', 'MKT', 'P2', null, 'Marketing Manager', array['audience', 'message', 'channel', 'urgency']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Draft communication, review and approve, send via selected channel, track responses.', 24),
  ('TPL-101', 'Brand Asset Request', 'Studio requests branded materials or assets.', 'Marketing', 'Brand', 'MKT', 'P3', null, 'Marketing Manager', array['assetType', 'purpose', 'quantity', 'deadline']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Source or design asset, get approval, produce, deliver to studio.', 168),
  ('TPL-102', 'Vendor Management Issue', 'Issue with a vendor — service quality, billing, or contract.', 'Operations', 'Vendor', 'MGT', 'P2', null, 'Operations Manager', array['vendorName', 'issueDescription', 'contractReference']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Document issue, contact vendor, escalate if needed, consider alternative vendors.', 72),
  ('TPL-103', 'Inventory Restocking', 'Studio supplies running low — needs restocking.', 'Operations', 'Inventory', 'FAC', 'P3', null, 'Maintenance Associate', array['studio', 'items', 'quantities']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify current inventory, place order, arrange delivery, update inventory log.', 48),
  ('TPL-104', 'Insurance Claim Documentation', 'Need to prepare documentation for insurance claim.', 'Operations', 'Insurance', 'MGT', 'P2', null, 'Operations Manager', array['claimType', 'incidentDate', 'amount']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Gather incident documentation, prepare claim, submit to insurer, follow up.', 168),
  ('TPL-105', 'Compliance Audit Request', 'Compliance audit or inspection scheduled.', 'Operations', 'Compliance', 'MGT', 'P2', null, 'Operations Manager', array['auditType', 'scheduledDate', 'scope']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Prepare documentation, coordinate with auditor, address findings, implement corrective actions.', 168),
  ('TPL-106', 'Studio Access Issue', 'Employee or client cannot access studio — key/lock/card issue.', 'Operations', 'Access', 'FAC', 'P1', null, 'Facilities Manager', array['affectedPerson', 'studio', 'issueDescription']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Verify authorization, replace key/card if needed, provide temporary access, document.', 4),
  ('TPL-107', 'Signage/Branding Update', 'Studio signage or branding needs update.', 'Operations', 'Branding', 'MKT', 'P3', null, 'Marketing Manager', array['studio', 'updateType', 'details']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Plan update, source vendor, schedule installation, verify completion.', 168),
  ('TPL-108', 'Emergency Drill', 'Schedule and conduct emergency drill.', 'Operations', 'Safety', 'MGT', 'P2', null, 'Operations Manager', array['studio', 'drillType', 'scheduledDate']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Plan drill, notify staff and clients, conduct drill, document outcomes, implement improvements.', 168),
  ('TPL-109', 'Studio Closure Notification', 'Need to close studio temporarily — needs notification.', 'Operations', 'Closure', 'MGT', 'P0', null, 'Studio Director', array['studio', 'closureReason', 'duration']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Notify all affected clients, cancel sessions, update Momence, post signage, arrange alternatives.', 2),
  ('TPL-110', 'Process Improvement Suggestion', 'Employee suggests a process improvement.', 'Operations', 'Process', 'MGT', 'P3', null, 'Operations Manager', array['suggestedBy', 'processArea', 'suggestion']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Review suggestion, evaluate feasibility, pilot if appropriate, implement if successful.', 168),
  ('TPL-111', 'Audit/Inspection Finding Resolution', 'Resolution required for audit/inspection finding.', 'Operations', 'Audit', 'MGT', 'P2', null, 'Operations Manager', array['findingDescription', 'auditType', 'dueDate']::text[], '[]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'Analyze finding, develop corrective action plan, implement, verify effectiveness, document.', 168)
