-- ---- Knowledge articles (25) -----------------------------------------------
insert into iris.knowledge_articles (id, title, category, summary, steps, prevention, escalation, related_templates) values
  ('KB-001', 'Hosted Class Feedback — Handling Member Proposals', 'Class Experience', 'How to handle member feedback on hosted class proposals, including corporate bookings and event coordination.', '["Acknowledge the feedback within 2 hours via email or WhatsApp","Review the proposal details — check if case studies and commercials were included","If the proposal was incomplete, escalate to Marketing (Mitali Kumar) for revision","Coordinate with the member to schedule a call within 48 hours to discuss next steps","Document the feedback in the hosted class tracker and notify the Sales team","Follow up with revised proposal within 3 business days"]'::jsonb, 'Ensure all hosted class proposals include case studies, commercials, and a clear timeline before sending to members', 'If member expresses embarrassment or dissatisfaction with the proposal quality, escalate to Studio Director immediately', array['TPL-076']::text[]),
  ('KB-002', 'Instructor Late for Class — Logging & Response', 'Trainer Feedback', 'Protocol for when an instructor arrives late for a scheduled class, including logging, member communication, and follow-up.', '["Log the incident immediately: trainer name, class time, arrival time, studio location","If trainer is more than 5 minutes late, notify the front desk to inform waiting clients","If class start is delayed by more than 10 minutes, offer clients the option to reschedule or attend a different class","For PowerCycle classes: late entry is only permitted within 5 minutes of class start","Send an internal incident report to the Studio Operations Manager by end of shift","If the trainer has repeated lateness (3+ incidents in a month), escalate to Training Manager for formal review","Document in the trainer''s punctuality record for monthly performance review"]'::jsonb, 'Ensure trainers confirm class times the evening before. Implement a 15-minute pre-class arrival requirement.', 'If trainer no-shows (does not arrive within 15 minutes of class start), arrange substitute immediately and escalate to Training Manager', array['TPL-072']::text[]),
  ('KB-003', 'Instructor Late Causing Class Cancellation', 'Trainer Feedback', 'When instructor lateness results in class cancellation — full resolution protocol including member compensation.', '["Notify all booked clients immediately via WhatsApp and email about the cancellation","Offer affected clients a complimentary class credit as service recovery","Arrange a substitute instructor if possible to avoid full cancellation","If no substitute available, cancel the class in Momence and credit all booked clients","File a formal incident report with the Studio Operations Manager within 1 hour","Conduct a root cause review with the trainer within 24 hours","If this is a repeat offence (2+ cancellations in a quarter), initiate formal performance review process","Follow up with affected clients within 48 hours to ensure satisfaction with recovery"]'::jsonb, 'Maintain a standby trainer list for each studio. Implement a 30-minute pre-class confirmation system.', 'Escalate to Studio Director and HR for formal performance management if repeat incidents occur', array['TPL-070']::text[]),
  ('KB-004', 'Member Arrived Late & Denied Entry', 'Class Experience', 'Handling members who arrive late and are denied entry per the Late Entry Policy (10-minute rule for regular classes, no grace for express classes).', '["Greet the member warmly and acknowledge their arrival — never make them feel unwelcome","Explain the late entry policy calmly: ''We have a 10-minute grace period for class safety and flow''","For express classes (Sweat in 30, etc.): No entry permitted once class has started","For PowerCycle: Grace period is only 5 minutes, and only for experienced riders (>10 classes)","Offer to reschedule the member to another class on the same day, subject to availability","If no same-day class available, credit the class back to the member''s package","For unlimited members: late cancellation/missed class does not deduct from their package","Document the incident if the member becomes upset — note their response for service recovery","If member disputes the policy, refer to the Late Entry Policy in the Brand Book and offer to have management follow up"]'::jsonb, 'Send pre-class reminders 2 hours before class. Display the late entry policy at reception.', 'If member becomes aggressive or threatens to cancel membership, escalate to Studio Director immediately', array['TPL-076']::text[]),
  ('KB-005', 'Studio Microphone Not Functioning', 'Repair and Maintenance', 'Troubleshooting steps for studio microphone malfunction — includes recurrence ticket creation protocol.', '["Check if the mic is powered on — verify battery level and replace if low","Test the microphone on a different receiver/channel to isolate the issue","Check all cable connections — XLR cable, receiver input, amplifier connection","If wireless mic: check if the frequency is properly synced to the receiver","If issue persists: swap with a backup microphone from the equipment storage","Log the malfunction in the maintenance log with timestamp and specific symptoms","Contact the AV vendor (AudioTech Solutions) for repair if hardware failure confirmed","Create a recurrence ticket: 5-day and 10-day follow-up checks assigned to the original reporter","Verify the repaired/replaced mic is functioning before the next class"]'::jsonb, 'Test all microphones 15 minutes before the first class each day. Keep spare batteries at the front desk.', 'If no backup mic available and classes are affected, escalate to Facilities Manager immediately as P0', array['TPL-034']::text[]),
  ('KB-006', 'Studio AC Red Light Blinking & Not Functioning', 'Repair and Maintenance', 'TCE/AC system malfunction — the red light indicates a fault code. Full troubleshooting and member communication protocol.', '["Check the AC unit''s display panel — note the fault code if displayed","Verify the thermostat is set correctly (18-22°C for studio floors)","Check if the TFA (Treated Fresh Air) system is running — it works in conjunction with the AC","Reset the AC unit by turning it off at the breaker, waiting 2 minutes, and turning it back on","If the red light persists after reset: this indicates a hardware fault requiring technician","Contact the HVAC vendor immediately with the fault code for diagnosis","If classes are in progress: provide portable fans and inform clients of the situation","Consider relocating affected classes to another studio if temperature exceeds 28°C","Communicate with booked clients for upcoming classes if the issue won''t be resolved before class","If AC has been non-functional for more than 24 hours, offer affected members compensation (class credit)"]'::jsonb, 'Schedule preventive HVAC maintenance quarterly. Check AC function during opening walkthrough.', 'If AC is non-functional for more than 48 hours or multiple complaints received, escalate to Studio Director', array['TPL-033']::text[]),
  ('KB-007', 'Membership Freeze Request — Injury or Medical', 'Pricing and Memberships', 'Processing a membership freeze due to injury or medical emergency. Includes policy on second freezes and medical documentation.', '["Verify the member''s current membership type and freeze eligibility","Check if the member has already used their annual freeze option","If first freeze: process immediately in Momence — set freeze start and end dates","If second freeze requested: requires management approval — escalate to Memberships Manager","For injury freezes: request medical certificate if absence exceeds 3 consecutive days","Set automatic unfreeze date in Momence (do not rely on manual unfreeze)","For medical emergencies: allow up to 30 days freeze without medical certificate initially","Confirm freeze details with the member via email — include start date, end date, and any billing implications","If the member has a class package (not unlimited): extend the package validity by the freeze duration","Log the freeze request and reason in the member''s Momence profile notes"]'::jsonb, 'Inform members of their freeze entitlement at sign-up. Display freeze policy at reception.', 'If member demands retrospective freeze or disputes freeze terms, escalate to Memberships Manager', array['TPL-011']::text[]),
  ('KB-008', 'Member Change/Addition of Class Time or Instructor', 'Scheduling', 'Handling member requests to change their booked class time, instructor, or class format.', '["Look up the member''s current booking in Momence using their name or phone","Verify the requested new class has available spots (check capacity in Momence)","If the requested class is full, offer to add the member to the waitlist","Check if the change is within the cancellation window (12 hours before original class)","If within window: process the change — cancel original booking and create new booking","If outside window: inform member it will be treated as a late cancellation","For instructor preference changes: check the schedule for the requested instructor''s upcoming classes","If the member wants a specific instructor regularly, note this preference in their Momence profile","Confirm the new booking with the member via WhatsApp or email","If the member is on an unlimited plan, no credit deduction needed for rebooking"]'::jsonb, 'Encourage members to use the app for self-service booking changes.', 'If member disputes a late cancellation charge related to a change request, escalate to Front Desk Lead', array['TPL-068']::text[]),
  ('KB-009', 'Studio Emergency Protocol', 'Safety and Security', 'Emergency response protocol for studio incidents — includes fire, medical emergency, security threat, and evacuation.', '["ASSESS: Evaluate the nature and severity of the emergency immediately","For MEDICAL EMERGENCY: Call 108 (ambulance) immediately, use the first aid kit, assign a staff member to wait at the entrance for the ambulance","For FIRE: Activate the fire alarm, evacuate all clients and staff via the nearest exit, assemble at the designated meeting point, call 101 (fire brigade)","For SECURITY THREAT: Lock the studio entrance, move clients away from the entrance, call 100 (police), do not engage with the threat","For EQUIPMENT FAILURE (electrical): Turn off the main power supply, evacuate the affected area, contact the maintenance vendor","Notify the Studio Director and Operations Manager immediately after initial response","Document the incident in detail: time, nature, people involved, actions taken, outcome","For any injury: Complete an incident report form and submit to management within 24 hours","Follow up with affected clients within 24 hours to check on their wellbeing","Conduct a debrief with the team within 48 hours to review response and identify improvements"]'::jsonb, 'Conduct emergency drills quarterly. Ensure all staff know emergency exits, first aid kit locations, and emergency contacts.', 'ALL emergencies must be escalated to the Studio Director immediately. Serious incidents require India Director notification within 1 hour.', array['TPL-077']::text[]),
  ('KB-010', 'PowerCycle Bike Malfunction — SC3 Troubleshooting', 'Repair and Maintenance', 'Troubleshooting Stages SC3 indoor bike issues — console, power meter, pedals, flywheel, belt drive. Includes recurrence protocol.', '["CONSOLE ISSUES: Check power connection — 3mm hex screws on the SIC2 console may be loose. Tighten with 3mm hex wrench.","POWER METER (SPM2): Check battery — if using AA batteries, ensure they''re not taped (use battery spacer). Zero reset ADC should read 790-990.","PEDAL ISSUES: Left pedal (CR-L) is REVERSE THREADED — turn clockwise to remove. Right pedal (CR-R) is standard thread.","FLYWHEEL/RESISTANCE: If resistance knob has no effect, the magnetic eddy-current brake may be misaligned. Requires technician.","BELT DRIVE: If you hear squeaking or feel slipping, the poly-V belt needs tension adjustment — requires technician service.","FITLOC LEVER: If handlebar won''t lock, check the quick-release lever is fully engaged (push down firmly).","SADDLE/SEAT: If saddle is loose, tighten the 13mm saddle clamp. Check saddle height alignment with hip bone.","STABILIZERS: If bike wobbles, adjust the 4 leveling feet (14mm nut) until stable.","LOG: Document the specific bike number, symptoms, and any parts replaced in the maintenance log","RECURRENCE: Create follow-up tickets for 5-day and 10-day checks — assigned to the original reporter for on-site verification"]'::jsonb, 'Inspect all bikes during opening walkthrough. Check pedal torque (42 N·m) monthly. Replace batteries quarterly.', 'If multiple bikes are affected or a bike is unsafe to ride, remove from service immediately and tag with ''OUT OF ORDER'' sign', array['TPL-035']::text[]),
  ('KB-011', 'Late Cancellation Policy Dispute — Member Pushback', 'Customer Service and Communication', 'Handling members who dispute late cancellation charges or booking privilege suspensions. Based on actual member issue patterns.', '["Review the member''s cancellation history in Momence — identify the specific late cancellations","Verify the policy: 3 late cancellations in any consecutive 7-day period triggers a 7-day booking block","Check if the cancellations were genuinely late (within 12 hours of class start for studio classes)","If the block was applied correctly: explain the policy calmly and reference the Brand Book","If the block was applied in error: remove it immediately and apologize for the inconvenience","For Unlimited members: explain they are allowed 2 late cancellations per calendar week before the block","For political bandh/force majeure situations: offer a goodwill exception and credit back the class","If member threatens cancellation: escalate to Memberships Manager for retention conversation","Log the dispute and outcome in the member''s profile notes for future reference","If the member has a pattern of disputing (3+ disputes), flag for management review"]'::jsonb, 'Send the late cancellation policy to all new members at sign-up. Display at reception.', 'If member threatens legal action or demands compensation beyond a class credit, escalate to Studio Director immediately', array['TPL-083']::text[]),
  ('KB-012', 'Valet Car Damage Incident', 'Theft and Lost Items', 'Protocol for when a member''s car is damaged by the studio valet service — incident reporting and member communication.', '["Acknowledge the incident immediately and express genuine concern","Document the damage: take photos of the damage, note the date, time, valet on duty, and car details","File a formal Incident Report within 1 hour of discovery","Notify the Studio Operations Manager and valet service company immediately","Provide the member with the valet service''s insurance contact information","Offer the member a complimentary class as a goodwill gesture","Follow up with the member within 24 hours to check on the repair process","Review valet staffing levels — if only one valet is on duty (vs. earlier 2-3), escalate to management","Document the incident in the incident log and notify the insurance team"]'::jsonb, 'Ensure valet service maintains adequate staffing. Conduct quarterly valet service review.', 'If member demands compensation or threatens legal action, escalate to Studio Director and legal team', array['TPL-077']::text[]),
  ('KB-013', 'Sound System Failure — Studio Audio Troubleshooting', 'Repair and Maintenance', 'Complete troubleshooting for studio sound system failures — amplifier, mixer, source device, and speaker chain.', '["Identify the scope: is it one speaker, one studio, or the whole system?","If one speaker: check the speaker cable connection at the amplifier end and the speaker end","If all speakers silent: check amplifier power LED, then check the mixer/output gain","Verify the source device (laptop/iPad) is playing audio and the output cable is connected","Check the mixer''s input gain — if it''s at zero, no audio will pass through","Test with a known-good source (e.g. a phone with a 3.5mm cable) to isolate source vs system issue","If amplifier shows a fault LED: power cycle the amp, wait 30 seconds, power on","If issue persists: contact AV vendor (AudioTech Solutions) with the specific symptom","Log the malfunction with timestamp, symptom, and resolution in the maintenance log","If classes are affected: arrange backup Bluetooth speaker for the next class only as a stopgap"]'::jsonb, 'Test the sound system 15 minutes before the first class each day. Verify cable connections during opening walkthrough.', 'If sound system is non-functional and a class is starting within 30 minutes, escalate to Facilities Manager immediately as P0', array['TPL-034']::text[]),
  ('KB-014', 'Member Complaint — Class Too Crowded', 'Class Experience', 'Handling member complaints about overcrowded classes — capacity management, member communication, and capacity review.', '["Acknowledge the member''s experience and apologize for the discomfort","Verify the class booking count vs the studio capacity in Momence","If overbooked: identify how the oversell happened (manual override, system glitch, waitlist auto-promotion)","Offer the member a complimentary class credit as service recovery","Review the waitlist logic — if a member was promoted from the waitlist beyond capacity, escalate to IT","If the class is regularly over capacity, consider adding a duplicate time slot or moving to a larger studio","Document the complaint with the specific class, instructor, and date","Follow up with the member on their next visit to ensure satisfaction"]'::jsonb, 'Set hard capacity limits in Momence. Train front desk to never override capacity without manager approval.', 'If multiple complaints about the same class within a week, escalate to Studio Director for capacity review', array['TPL-076']::text[]),
  ('KB-015', 'Lost Item — Member''s Personal Belonging', 'Theft and Lost Items', 'Protocol for handling lost item reports — locker checks, surveillance review, and member follow-up.', '["Acknowledge the report and gather details: item description, last-seen location, time","Check the locker the member used — items often fall behind or under benches","Check the lost-and-found bin at the front desk","If not found immediately, log the lost item report with full description and member contact","Review CCTV footage of the locker area for the relevant time window (front desk staff only)","If item is found in footage being picked up by another member, escalate to Studio Director","Contact the member within 24 hours with an update — found or still-missing","If still missing after 48 hours, offer to file a formal lost item claim","Tag high-value items (jewellery, electronics) in the lost-and-found log with a ''priority return'' flag"]'::jsonb, 'Remind members to lock lockers and take valuables. Provide a valuables tray at the front desk for high-value items.', 'If item is high-value (>₹10,000) or appears stolen, escalate to Studio Director and review CCTV with management', array['TPL-077']::text[]),
  ('KB-016', 'Class Cancellation — Instructor Unavailable', 'Scheduling', 'Protocol for cancelling a class when the instructor becomes unavailable at short notice — substitute finding, member notification, and credit handling.', '["Confirm the instructor''s unavailability and the reason (medical, emergency, no-show)","Check the substitute trainer list for that studio and class format","Call substitutes in order of preference — start with the most senior trainer for that format","If a substitute is found: update Momence with the new instructor and notify booked clients","If no substitute available: cancel the class in Momence at least 60 minutes before start time if possible","Notify all booked clients via WhatsApp and email about the cancellation","Credit all booked clients automatically (Momence handles this for cancellations)","For Unlimited members: no impact on their package","For class package members: credit the class back automatically","File an incident report if the cancellation was due to a no-show (vs. communicated unavailability)","Follow up with affected clients in the next 48 hours for service recovery"]'::jsonb, 'Maintain a standby trainer list for each studio and class format. Implement a 4-hour pre-class confirmation system with instructors.', 'If instructor no-shows (no communication) more than once in a quarter, escalate to Training Manager for formal performance review', array['TPL-070']::text[]),
  ('KB-017', 'Payment Dispute — Member Claims Double Charge', 'Pricing and Memberships', 'Investigating and resolving member claims of being charged twice for the same service or membership.', '["Gather details from the member: dates of both charges, amounts, and last 4 digits of card","Look up the member''s transaction history in Momence","Cross-reference with payment gateway records for the specified dates","If two transactions exist for the same item within 24 hours: this is a confirmed double charge","Process a refund for the duplicate transaction through the payment gateway","Notify the member via email with the refund reference number and expected processing time","If only one transaction exists but member sees two on their statement: explain this may be a bank authorization hold","Provide the member with the single transaction ID for their records","If bank authorization hold: advise the member it will release within 3-7 business days","Log the dispute and resolution in the member''s profile notes"]'::jsonb, 'Ensure payment gateway has duplicate detection enabled. Train front desk to verify successful payment before retrying.', 'If dispute cannot be resolved within 48 hours or involves amount >₹10,000, escalate to Finance Manager', array['TPL-021']::text[]),
  ('KB-018', 'Membership Refund Processing — Full Workflow', 'Pricing and Memberships', 'Complete refund processing workflow from request to reconciliation, including approval routing based on amount.', '["Verify the original payment in Momence — date, amount, payment method, transaction ID","Check the refund eligibility per policy: within cooling-off period, service not delivered, billing error","Determine refund type: full, partial, or credit to account","For refunds under ₹5,000: Front Desk Lead can approve","For refunds ₹5,000-₹25,000: Memberships Manager approval required","For refunds over ₹25,000: Studio Director approval required","Process the refund through the original payment gateway (Razorpay/Pine Labs)","Generate the refund reference number and record in Momence","Notify the member via email with refund reference and expected processing time","For UPI refunds: typically processed within 1-3 business days","For card refunds: typically processed within 5-7 business days","Follow up with the member after the expected processing window to confirm receipt","Mark the refund as ''completed'' in Momence once member confirms receipt"]'::jsonb, 'Document refund policy clearly at sign-up. Train front desk on the approval matrix.', 'If refund is not processed within the SLA window, escalate to Finance Manager for status check', array['TPL-029']::text[]),
  ('KB-019', 'Studio Equipment Damage — Member Caused', 'Repair and Maintenance', 'Handling cases where a member damages studio equipment during a class — assessment, member communication, and repair routing.', '["Assess the damage immediately — is the equipment safe to continue using or must it be taken out of service?","If unsafe: tag with ''OUT OF ORDER'' sign and remove from the studio floor","Identify the member responsible — confirm with the instructor and any witnesses","Approach the member privately after class, never in front of other members","Explain what happened and ask for their account of the incident","Determine if damage was accidental (normal use) or negligence (misuse)","For accidental damage: do not charge the member; route through insurance if applicable","For negligence (e.g. dropped weights, forced equipment): discuss cost recovery with Studio Director","Log the damage with photos, equipment serial number, and member details in the incident log","Contact the equipment vendor for repair quote within 24 hours","If repair cost >₹5,000, escalate to Studio Director for cost recovery decision","Replace equipment or arrange repair based on vendor recommendation"]'::jsonb, 'Display equipment usage guidelines in the studio. Instructors to give form corrections proactively to prevent misuse.', 'If member disputes responsibility or refuses to provide details, escalate to Studio Director', array['TPL-077']::text[]),
  ('KB-020', 'First Aid Incident — Member Injury During Class', 'Safety and Security', 'Response protocol when a member is injured during a class — first aid, incident documentation, and follow-up.', '["Stop the class immediately and ensure the injured member is safe","Assess the injury severity — minor (cut, bruise) vs major (sprain, fracture, head injury)","For minor injuries: provide first aid from the studio kit (bandages, antiseptic, ice pack)","For major injuries: call 108 (ambulance) immediately and assign a staff member to wait at entrance","Do not move the member if a spinal or head injury is suspected","Provide the member with water and a place to sit while waiting for ambulance","Notify the Studio Director and Operations Manager immediately","Document the incident in detail: time, class, instructor, member name, what happened, actions taken","Take photos of the scene if relevant (e.g. equipment that caused the injury)","Complete the formal incident report form within 24 hours","Contact the member''s emergency contact if they consent or if incapacitated","Follow up with the member within 24 hours to check on their condition","Conduct a debrief with the team to identify any preventive actions"]'::jsonb, 'Ensure all staff are first-aid trained. Inspect equipment for safety before each class. Maintain a well-stocked first aid kit.', 'ALL major injuries must be escalated to the Studio Director immediately. Serious injuries require India Director notification within 1 hour.', array['TPL-077']::text[]),
  ('KB-021', 'Front Desk — Handling Walk-In Inquiries', 'Customer Service and Communication', 'Standard protocol for handling walk-in inquiries — trial class requests, pricing questions, and studio tours.', '["Greet the visitor within 10 seconds of them entering — stand up, smile, make eye contact","Ask: ''Hi, welcome to Physique 57! How can I help you today?''","For trial class requests: explain the newcomer offer (2-for-1 trial) and check availability","Book the trial in Momence if they want to proceed — collect name, phone, email","For pricing questions: walk through the membership options brochure, highlight the most popular package","Offer a 5-minute studio tour — show the barre area, locker room, and reception","During the tour, mention class formats briefly (Barre, Cardio Barre, Sculpt, PowerCycle)","After the tour, ask if they have any questions or would like to book a trial","If they''re not ready to commit: take their contact info for follow-up, give them a brochure","Log the walk-in in the front desk log with their interest level (high/medium/low)","Follow up via WhatsApp within 24 hours if contact info was provided"]'::jsonb, 'Train all front desk staff on the walk-in script. Ensure the studio is always tour-ready.', 'If visitor indicates they''re a competitor (asking detailed operational questions), notify Studio Director discreetly', array['TPL-076']::text[]),
  ('KB-022', 'Trainer Performance Concern — Member Feedback', 'Trainer Feedback', 'Handling member feedback that raises concerns about a trainer''s performance — documentation, investigation, and coaching trigger.', '["Listen actively to the member and acknowledge their feedback — never dismiss or defend","Take detailed notes: trainer name, class date, specific concerns, member''s name and contact","Ask clarifying questions to understand the specifics — what happened, when, impact on the member","Do not promise specific outcomes — say ''I''ll look into this and follow up with you''","Thank the member for the feedback — it helps us improve","If the concern is about safety (e.g. unsafe corrections, inappropriate behaviour): escalate immediately to Studio Director","For performance concerns (cueing, music, pacing): log in the trainer''s feedback file for the monthly review","Review the trainer''s recent assessments and other member feedback to check for patterns","If pattern emerges (3+ similar concerns in a month): trigger a coaching conversation with the Training Manager","Conduct the coaching conversation privately, fact-based, with specific examples","Follow up with the member within 48 hours to confirm the feedback was received and acted upon","Document the resolution in the trainer''s file and the member''s profile notes"]'::jsonb, 'Conduct quarterly anonymous member feedback surveys. Train instructors on the feedback-acknowledgement protocol.', 'If feedback involves harassment, discrimination, or safety: escalate to Studio Director AND HR immediately. Do not investigate independently.', array['TPL-072']::text[]),
  ('KB-023', 'PowerCycle Class — Bike Setup & Member Onboarding', 'Class Experience', 'Proper bike setup protocol for new PowerCycle members — fit adjustment, safety briefing, and late entry rules.', '["Welcome the member to their first PowerCycle class and confirm they''re new","Help them set up the bike: saddle height aligned with hip bone when standing next to the bike","Adjust saddle fore/aft: knee over pedal spindle when foot is at 3 o''clock position","Set handlebar height: slightly above saddle for beginners, level for experienced riders","Verify the Fitloc lever is fully engaged (push down firmly until it clicks)","Verify cleats are properly attached if using cycling shoes, or sneakers are flat on platform pedals","Provide a 2-minute safety briefing: emergency brake (resistance knob pressed down), foot release technique","Explain the console: cadence (RPM), power output (watts), and how to read the colors","For first-timers: recommend keeping resistance low and focusing on form over output","Explain late entry rule: PowerCycle allows entry only within 5 minutes of class start, and only for experienced riders (>10 classes)","Check that the member''s water bottle is in the cage and towel is accessible","Confirm the member knows the instructor''s name for any in-class questions"]'::jsonb, 'Train all PowerCycle instructors to proactively offer setup help to new members. Maintain a ''newbie'' tag visible to instructors in Momence booking list.', 'If member experiences discomfort or pain during setup that suggests prior injury, advise them to consult a physician before continuing', array['TPL-035']::text[]),
  ('KB-024', 'Studio Closing — Emergency or Maintenance', 'Safety and Security', 'Protocol for emergency or planned studio closure — member notification, class cancellation, and reopening checks.', '["Determine the closure reason: emergency (flood, fire, electrical), maintenance (HVAC, equipment), or external (bandh, government order)","Estimate the closure duration: hours, day, multi-day","Notify the Studio Director and Operations Manager immediately — they make the official closure call","Cancel all classes in Momence from the closure start time to expected end time","Auto-credit all booked members for cancelled classes (Momence handles this)","Notify all affected members via WhatsApp broadcast and email — include reason, expected duration, and next steps","Update the studio''s automated phone greeting with closure information","Post a closure notice on the studio entrance with contact info for urgent queries","For emergency closures: contact the relevant vendor (HVAC, electrician, fire restoration) immediately","For planned closures: notify members at least 48 hours in advance when possible","Maintain a closure log with timestamps, reason, vendor contacts, and reopening checks","Before reopening: conduct a full safety walkthrough (equipment, floors, AC, sound, lights)","Notify members of reopening via the same channels used for closure"]'::jsonb, 'Maintain vendor contact list for all critical systems. Conduct quarterly emergency drill including closure protocol.', 'Multi-day closures or closures affecting >200 members require India Director notification within 2 hours', array['TPL-077']::text[]),
  ('KB-025', 'Member Cancellation — Retention Conversation', 'Customer Service and Communication', 'Conducting a retention conversation when a member requests cancellation — understanding root cause, offering alternatives, and graceful processing if cancellation proceeds.', '["Acknowledge the member''s decision without defensiveness — ''I''m sorry to hear that, can I ask what''s prompting the cancellation?''","Listen actively to identify the root cause: relocation, financial, dissatisfaction, medical, time constraints","For relocation: offer membership transfer to a city with a P57 studio, or pause with no fee","For financial: discuss downgrade options, pause, or payment plan if eligible","For dissatisfaction: probe for specifics — class experience, instructor, facility, scheduling","If specific dissatisfaction: offer to address it (e.g. different instructor, alternate class time)","For medical: process freeze instead of cancellation if eligible","For time constraints: offer a reduced-attendance package or pause","If member still wants to cancel after the conversation: process respectfully, no pressure","Confirm cancellation terms: end date, final billing, access end date","Process cancellation in Momence with the agreed terms","Send a cancellation confirmation email with all details","Log the cancellation reason and any retention offer made in the member''s profile","Schedule a ''win-back'' outreach 60 days after cancellation"]'::jsonb, 'Conduct proactive check-ins with members at month 3 and month 6 of their membership to catch dissatisfaction early.', 'If cancellation volume exceeds 5% of active members in a month, escalate to Studio Director for retention strategy review', array['TPL-004']::text[])
on conflict (id) do update set title = excluded.title, category = excluded.category, summary = excluded.summary,
  steps = excluded.steps, prevention = excluded.prevention, escalation = excluded.escalation,
  related_templates = excluded.related_templates;

