  ('51913602106', 'trn_anisha_shah', 'Anisha Shah', 'IRIS-2026-1427', 'Supreme HQ, Mumbai', '2026-02-22T13:02:35.494Z'::timestamptz, 72, 'Average', 'amber', '{"id":51913602106,"ticketNumber":"IRIS-2026-1427","studio":"Supreme HQ, Mumbai","createdAt":"2026-02-22T13:02:35.494Z","submittedAt":"2026-02-22T13:02:35.494Z","score":72,"evaluator":"Reyaan Malhotra","title":"Barre Class — Beginner — assessment","band":"Average","bandTone":"amber","sourceLabel":"Training Quality Assessment — by staff","sessionName":"Barre Class — Beginner","strengths":"Confident demonstration of complex sequences. Gave clear, layered cues that beginners could follow.","improvements":"A couple of form corrections missed — be more proactive with hands-on adjustments during the thigh section.","coachingPlan":"Focus the next two weeks on modification cues — pair with a senior trainer for shadow teaching during the 6 PM class.","summary":"Anisha Shah''s barre class — beginner on 22 Feb. Scored 72% (Average).","rubric":[{"category":"Pre-Class Setup & Vibe","score":7.3,"weightage":10,"pct":73},{"category":"Cueing & Instruction","score":10.4,"weightage":15,"pct":69},{"category":"Demonstration & Form","score":10.4,"weightage":15,"pct":69},{"category":"Music & Tempo","score":6.6,"weightage":10,"pct":66},{"category":"Class Flow & Pacing","score":9.1,"weightage":12,"pct":76},{"category":"Member Corrections","score":9.4,"weightage":13,"pct":72},{"category":"Energy & Presence","score":7,"weightage":10,"pct":70},{"category":"Safety & Modifications","score":12,"weightage":15,"pct":80}],"answers":[{"label":"Trainer","value":"Anisha Shah"},{"label":"Session","value":"Barre Class — Beginner"},{"label":"Studio","value":"Supreme HQ, Mumbai"},{"label":"Evaluator","value":"Reyaan Malhotra"},{"label":"Submitted","value":"22 Feb 2026"},{"label":"Overall band","value":"Average"}]}'::jsonb),
  ('51913602105', 'trn_anisha_shah', 'Anisha Shah', 'IRIS-2026-1426', 'Kwality House, Mumbai', '2026-04-01T13:02:35.529Z'::timestamptz, 71, 'Average', 'amber', '{"id":51913602105,"ticketNumber":"IRIS-2026-1426","studio":"Kwality House, Mumbai","createdAt":"2026-04-01T13:02:35.529Z","submittedAt":"2026-04-01T13:02:35.529Z","score":71,"evaluator":"Studio Director","title":"Sculpt & Tone — assessment","band":"Average","bandTone":"amber","sourceLabel":"Training Quality Assessment — by staff","sessionName":"Sculpt & Tone","strengths":"Great rapport with the regular members; remembered names and offered personalised encouragement.","improvements":"Final stretch felt rushed. Add 30 seconds to the cooldown so members don''t feel they''re being pushed out.","coachingPlan":"Review the music playlist for the next class with the Studio Operations Manager; align tempo to the choreography notes.","summary":"Anisha Shah''s sculpt & tone on 1 Apr. Scored 71% (Average).","rubric":[{"category":"Pre-Class Setup & Vibe","score":6.5,"weightage":10,"pct":65},{"category":"Cueing & Instruction","score":10.1,"weightage":15,"pct":67},{"category":"Demonstration & Form","score":11.9,"weightage":15,"pct":79},{"category":"Music & Tempo","score":7.3,"weightage":10,"pct":73},{"category":"Class Flow & Pacing","score":8.8,"weightage":12,"pct":73},{"category":"Member Corrections","score":9,"weightage":13,"pct":69},{"category":"Energy & Presence","score":6.6,"weightage":10,"pct":66},{"category":"Safety & Modifications","score":11,"weightage":15,"pct":73}],"answers":[{"label":"Trainer","value":"Anisha Shah"},{"label":"Session","value":"Sculpt & Tone"},{"label":"Studio","value":"Kwality House, Mumbai"},{"label":"Evaluator","value":"Studio Director"},{"label":"Submitted","value":"1 Apr 2026"},{"label":"Overall band","value":"Average"}]}'::jsonb),
